CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','erased')), created_at INTEGER NOT NULL);
CREATE TABLE communities (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, owner_id INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE TABLE memberships (community_id INTEGER NOT NULL REFERENCES communities(id), user_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','moderator','member')), joined_at INTEGER NOT NULL, PRIMARY KEY(community_id,user_id));
CREATE TABLE boards (id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER NOT NULL REFERENCES communities(id), slug TEXT NOT NULL, title TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('public','members','staff')), requires_review INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, UNIQUE(community_id,slug));
CREATE TABLE topics (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL REFERENCES boards(id), author_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','published','locked','hidden','archived')), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL REFERENCES topics(id), author_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'visible' CHECK(state IN ('visible','hidden','erased')), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER NOT NULL REFERENCES posts(id), editor_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE reports (id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER NOT NULL REFERENCES posts(id), reporter_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','dismissed','upheld')), resolution TEXT, moderator_id INTEGER REFERENCES users(id), created_at INTEGER NOT NULL, resolved_at INTEGER, UNIQUE(post_id,reporter_id));
CREATE TABLE sanctions (id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER NOT NULL REFERENCES communities(id), user_id INTEGER NOT NULL REFERENCES users(id), moderator_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE subscriptions (topic_id INTEGER NOT NULL REFERENCES topics(id), user_id INTEGER NOT NULL REFERENCES users(id), PRIMARY KEY(topic_id,user_id));
CREATE TABLE bookmarks (topic_id INTEGER NOT NULL REFERENCES topics(id), user_id INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, PRIMARY KEY(topic_id,user_id));
CREATE TABLE reactions (post_id INTEGER NOT NULL REFERENCES posts(id), user_id INTEGER NOT NULL REFERENCES users(id), reaction TEXT NOT NULL CHECK(reaction IN ('helpful','thanks','agree')), PRIMARY KEY(post_id,user_id));
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), topic_id INTEGER NOT NULL REFERENCES topics(id), event_id INTEGER NOT NULL, message TEXT NOT NULL, read_at INTEGER, created_at INTEGER NOT NULL, UNIQUE(user_id,event_id));
CREATE TABLE outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL REFERENCES topics(id), actor_id INTEGER NOT NULL REFERENCES users(id), message TEXT NOT NULL, created_at INTEGER NOT NULL, delivered_at INTEGER);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER REFERENCES users(id), community_id INTEGER REFERENCES communities(id), action TEXT NOT NULL, subject TEXT NOT NULL, details TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE idempotency (user_id INTEGER NOT NULL REFERENCES users(id), key TEXT NOT NULL, fingerprint TEXT NOT NULL, resource_id INTEGER NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,key));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE INDEX topics_board_activity ON topics(board_id,state,updated_at,id);
CREATE INDEX posts_topic ON posts(topic_id,id);
CREATE INDEX reports_queue ON reports(state,created_at);
CREATE INDEX sanctions_active ON sanctions(community_id,user_id,expires_at);
CREATE INDEX outbox_pending ON outbox(delivered_at,id);
CREATE INDEX notifications_inbox ON notifications(user_id,read_at,id);
CREATE INDEX audit_retention ON audit(created_at);
